308→+package main
309→+
310→+import (
311→+	"bytes"
312→+	"context"
313→+	"crypto/hmac"
314→+	"crypto/sha256"
315→+	"encoding/hex"
316→+	"encoding/json"
317→+	"errors"
318→+	"fmt"
319→+	"io"
320→+	"log"
321→+	"net/http"
322→+	"net/url"
323→+	"os"
324→+	"strconv"
325→+	"strings"
326→+	"time"
327→+
328→+	"github.com/entireio/cli/internal/slacktriage"
329→+)
330→+
331→+const (
332→+	defaultAddr                = ":8080"
333→+	defaultGitHubAPIBaseURL    = "https://api.github.com"
334→+	defaultSlackAPIBaseURL     = "https://slack.com/api"
335→+	defaultSlackEventType      = "slack_e2e_triage_requested"
336→+	defaultRequestTolerance    = 5 * time.Minute
337→+	slackTimestampHeader       = "X-Slack-Request-Timestamp"
338→+	slackSignatureHeader       = "X-Slack-Signature"
339→+	slackEventTypeURLVerify    = "url_verification"
340→+	slackEventTypeCallback     = "event_callback"
341→+	slackInnerEventTypeMessage = "message"
342→+)
343→+
344→+// Config holds runtime settings loaded from the environment.
345→+type Config struct {
346→+	Addr             string
347→+	SigningSecret    string
348→+	SlackBotToken    string
349→+	GitHubToken      string
350→+	AllowedRepo      string
351→+	GitHubEventType  string
352→+	SlackAPIBaseURL  string
353→+	GitHubAPIBaseURL string
354→+	RequestTolerance time.Duration
355→+}
356→+
357→+func main() {
358→+	cfg, err := loadConfigFromEnv()
359→+	if err != nil {
360→+		log.Fatal(err)
361→+	}
362→+
363→+	handler := newHandler(
364→+		cfg,
365→+		newSlackHTTPClient(cfg.SlackBotToken, cfg.SlackAPIBaseURL),
366→+		newGitHubHTTPDispatcher(cfg.GitHubToken, cfg.GitHubAPIBaseURL, cfg.GitHubEventType, cfg.AllowedRepo),
367→+		time.Now,
368→+	)
369→+
370→+	mux := http.NewServeMux()
371→+	mux.Handle("/slack/events", handler)
372→+
373→+	srv := &http.Server{
374→+		Addr:              cfg.Addr,
375→+		Handler:           mux,
376→+		ReadHeaderTimeout: 5 * time.Second,
377→+	}
378→+	log.Fatal(srv.ListenAndServe())
379→+}
380→+
381→+func loadConfigFromEnv() (Config, error) {
382→+	cfg := Config{
383→+		Addr:             getEnvDefault("ADDR", defaultAddr),
384→+		SigningSecret:    os.Getenv("SLACK_SIGNING_SECRET"),
385→+		SlackBotToken:    os.Getenv("SLACK_BOT_TOKEN"),
386→+		GitHubToken:      os.Getenv("GITHUB_TOKEN"),
387→+		AllowedRepo:      getEnvFirst("ALLOWED_REPOSITORY", "GITHUB_REPOSITORY"),
388→+		GitHubEventType:  getEnvDefault("GITHUB_EVENT_TYPE", defaultSlackEventType),
389→+		SlackAPIBaseURL:  getEnvDefault("SLACK_API_BASE_URL", defaultSlackAPIBaseURL),
390→+		GitHubAPIBaseURL: getEnvDefault("GITHUB_API_BASE_URL", defaultGitHubAPIBaseURL),
391→+		RequestTolerance: defaultRequestTolerance,
392→+	}
393→+
394→+	if tolerance := os.Getenv("SLACK_REQUEST_TOLERANCE"); tolerance != "" {
395→+		d, err := time.ParseDuration(tolerance)
396→+		if err != nil {
397→+			return Config{}, fmt.Errorf("parse SLACK_REQUEST_TOLERANCE: %w", err)
398→+		}
399→+		cfg.RequestTolerance = d
400→+	}
401→+
402→+	switch {
403→+	case cfg.SigningSecret == "":
404→+		return Config{}, errors.New("SLACK_SIGNING_SECRET is required")
405→+	case cfg.SlackBotToken == "":
406→+		return Config{}, errors.New("SLACK_BOT_TOKEN is required")
407→+	case cfg.GitHubToken == "":
408→+		return Config{}, errors.New("GITHUB_TOKEN is required")
409→+	case cfg.AllowedRepo == "":
410→+		return Config{}, errors.New("ALLOWED_REPOSITORY or GITHUB_REPOSITORY is required")
411→+	default:
412→+		return cfg, nil
413→+	}
414→+}
415→+
416→+func getEnvDefault(key, fallback string) string {
417→+	if value := os.Getenv(key); value != "" {
418→+		return value
419→+	}
420→+	return fallback
421→+}
422→+
423→+func getEnvFirst(keys ...string) string {
424→+	for _, key := range keys {
425→+		if value := os.Getenv(key); value != "" {
426→+			return value
427→+		}
428→+	}
429→+	return ""
430→+}
431→+
432→+type SlackMessageFetcher interface {
433→+	FetchParentMessage(ctx context.Context, channel, threadTS string) (string, error)
434→+}
435→+
436→+type GitHubDispatcher interface {
437→+	DispatchRepositoryEvent(ctx context.Context, payload slacktriage.DispatchPayload) error
438→+}
439→+
440→+type triageHandler struct {
441→+	cfg        Config
442→+	slack      SlackMessageFetcher
443→+	github     GitHubDispatcher
444→+	now        func() time.Time
445→+	maxBodyLen int64
446→+}
447→+
448→+func newHandler(cfg Config, slack SlackMessageFetcher, github GitHubDispatcher, now func() time.Time) *triageHandler {
449→+	if now == nil {
450→+		now = time.Now
451→+	}
452→+	if cfg.RequestTolerance <= 0 {
453→+		cfg.RequestTolerance = defaultRequestTolerance
454→+	}
455→+
456→+	return &triageHandler{
457→+		cfg:        cfg,
458→+		slack:      slack,
459→+		github:     github,
460→+		now:        now,
461→+		maxBodyLen: 1 << 20,
462→+	}
463→+}
464→+
465→+func (h *triageHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
466→+	if r.Method != http.MethodPost {
467→+		http.Error(w, http.StatusText(http.StatusMethodNotAllowed), http.StatusMethodNotAllowed)
468→+		return
469→+	}
470→+	defer r.Body.Close()
471→+
472→+	body, err := io.ReadAll(io.LimitReader(r.Body, h.maxBodyLen))
473→+	if err != nil {
474→+		http.Error(w, "read request body", http.StatusBadRequest)
475→+		return
476→+	}
477→+
478→+	if err := h.verifyRequest(r, body); err != nil {
479→+		http.Error(w, http.StatusText(http.StatusUnauthorized), http.StatusUnauthorized)
480→+		return
481→+	}
482→+
483→+	var envelope slackEnvelope
484→+	if err := json.Unmarshal(body, &envelope); err != nil {
485→+		http.Error(w, "decode slack payload", http.StatusBadRequest)
486→+		return
487→+	}
488→+
489→+	switch envelope.Type {
490→+	case slackEventTypeURLVerify:
491→+		writeJSON(w, http.StatusOK, map[string]string{"challenge": envelope.Challenge})
492→+	case slackEventTypeCallback:
493→+		if err := h.handleEvent(r.Context(), envelope.Event); err != nil {
494→+			http.Error(w, "process slack event", http.StatusInternalServerError)
495→+			return
496→+		}
497→+		w.WriteHeader(http.StatusOK)
498→+	default:
499→+		w.WriteHeader(http.StatusOK)
500→+	}
501→+}
502→+
503→+func (h *triageHandler) verifyRequest(r *http.Request, body []byte) error {
504→+	timestamp := r.Header.Get(slackTimestampHeader)
505→+	signature := r.Header.Get(slackSignatureHeader)
506→+	if timestamp == "" || signature == "" {
507→+		return errors.New("missing slack signature headers")
508→+	}
509→+
510→+	parsed, err := strconv.ParseInt(timestamp, 10, 64)
511→+	if err != nil {
512→+		return fmt.Errorf("invalid slack timestamp: %w", err)
513→+	}
514→+
515→+	requestTime := time.Unix(parsed, 0)
516→+	now := h.now()
517→+	if absDuration(now.Sub(requestTime)) > h.cfg.RequestTolerance {
518→+		return errors.New("stale slack request")
519→+	}
520→+
521→+	mac := hmac.New(sha256.New, []byte(h.cfg.SigningSecret))
522→+	if _, err := mac.Write([]byte("v0:" + timestamp + ":" + string(body))); err != nil {
523→+		return fmt.Errorf("sign slack request: %w", err)
524→+	}
525→+	expected := "v0=" + hex.EncodeToString(mac.Sum(nil))
526→+	if !hmac.Equal([]byte(expected), []byte(signature)) {
527→+		return errors.New("invalid slack signature")
528→+	}
529→+
530→+	return nil
531→+}
532→+
533→+func (h *triageHandler) handleEvent(ctx context.Context, event slackEvent) error {
534→+	if event.Type != slackInnerEventTypeMessage {
535→+		return nil
536→+	}
537→+	if event.Subtype != "" || event.BotID != "" {
538→+		return nil
539→+	}
540→+	if event.ThreadTS == "" || event.ThreadTS == event.Ts {
541→+		return nil
542→+	}
543→+	if !slacktriage.IsTriageTrigger(event.Text) {
544→+		return nil
545→+	}
546→+	if h.slack == nil {
547→+		return errors.New("slack fetcher is not configured")
548→+	}
549→+	if h.github == nil {
550→+		return errors.New("github dispatcher is not configured")
551→+	}
552→+	if event.Channel == "" {
553→+		return errors.New("channel is required")
554→+	}
555→+
556→+	parentBody, err := h.slack.FetchParentMessage(ctx, event.Channel, event.ThreadTS)
557→+	if err != nil {
558→+		return fmt.Errorf("fetch parent message: %w", err)
559→+	}
560→+
561→+	metadata, err := slacktriage.ParseParentMessageMetadata(parentBody)
562→+	if err != nil {
563→+		return fmt.Errorf("parse parent message metadata: %w", err)
564→+	}
565→+	if h.cfg.AllowedRepo != "" && metadata.Repo != h.cfg.AllowedRepo {
566→+		return nil
567→+	}
568→+
569→+	payload := slacktriage.NewDispatchPayload(metadata, event.Channel, event.ThreadTS, event.User)
570→+	if err := h.github.DispatchRepositoryEvent(ctx, payload); err != nil {
571→+		return fmt.Errorf("dispatch repository event: %w", err)
572→+	}
573→+	return nil
574→+}
575→+
576→+type slackEnvelope struct {
577→+	Type      string     `json:"type"`
578→+	Challenge string     `json:"challenge,omitempty"`
579→+	Event     slackEvent `json:"event,omitempty"`
580→+}
581→+
582→+type slackEvent struct {
583→+	Type     string `json:"type,omitempty"`
584→+	Subtype  string `json:"subtype,omitempty"`
585→+	BotID    string `json:"bot_id,omitempty"`
586→+	Channel  string `json:"channel,omitempty"`
587→+	User     string `json:"user,omitempty"`
588→+	Text     string `json:"text,omitempty"`
589→+	Ts       string `json:"ts,omitempty"`
590→+	ThreadTS string `json:"thread_ts,omitempty"`
591→+}
592→+
593→+func writeJSON(w http.ResponseWriter, status int, value any) {
594→+	w.Header().Set("Content-Type", "application/json; charset=utf-8")
595→+	w.WriteHeader(status)
596→+	if err := json.NewEncoder(w).Encode(value); err != nil {
597→+		log.Printf("write json response: %v", err)
598→+	}
599→+}
600→+
601→+func absDuration(d time.Duration) time.Duration {
602→+	if d < 0 {
603→+		return -d
604→+	}
605→+	return d
606→+}
607→+
608→+type slackHTTPClient struct {
609→+	token   string
610→+	baseURL string
611→+	client  *http.Client
612→+}
613→+
614→+func newSlackHTTPClient(token, baseURL string) *slackHTTPClient {
615→+	if baseURL == "" {
616→+		baseURL = defaultSlackAPIBaseURL
617→+	}
618→+	return &slackHTTPClient{
619→+		token:   token,
620→+		baseURL: strings.TrimRight(baseURL, "/"),
621→+		client:  &http.Client{Timeout: 10 * time.Second},
622→+	}
623→+}
624→+
625→+func (c *slackHTTPClient) FetchParentMessage(ctx context.Context, channel, threadTS string) (string, error) {
626→+	endpoint, err := url.Parse(c.baseURL + "/conversations.replies")
627→+	if err != nil {
628→+		return "", fmt.Errorf("parse slack conversations.replies url: %w", err)
629→+	}
630→+
631→+	query := endpoint.Query()
632→+	query.Set("channel", channel)
633→+	query.Set("ts", threadTS)
634→+	query.Set("inclusive", "true")
635→+	query.Set("limit", "1")
636→+	endpoint.RawQuery = query.Encode()
637→+
638→+	req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint.String(), nil)
639→+	if err != nil {
640→+		return "", fmt.Errorf("build slack conversations.replies request: %w", err)
641→+	}
642→+	req.Header.Set("Authorization", "Bearer "+c.token)
643→+
644→+	//nolint:gosec // Slack API base URL is operator-configured.
645→+	resp, err := c.client.Do(req)
646→+	if err != nil {
647→+		return "", fmt.Errorf("call slack conversations.replies: %w", err)
648→+	}
649→+	defer resp.Body.Close()
650→+
651→+	if resp.StatusCode != http.StatusOK {
652→+		return "", fmt.Errorf("slack conversations.replies returned %s", resp.Status)
653→+	}
654→+
655→+	var payload struct {
656→+		OK       bool   `json:"ok"`
657→+		Error    string `json:"error,omitempty"`
658→+		Messages []struct {
659→+			Text string `json:"text"`
660→+		} `json:"messages"`
661→+	}
662→+	if err := json.NewDecoder(resp.Body).Decode(&payload); err != nil {
663→+		return "", fmt.Errorf("decode slack conversations.replies response: %w", err)
664→+	}
665→+	if !payload.OK {
666→+		if payload.Error == "" {
667→+			payload.Error = "unknown error"
668→+		}
669→+		return "", fmt.Errorf("slack conversations.replies error: %s", payload.Error)
670→+	}
671→+	if len(payload.Messages) == 0 {
672→+		return "", errors.New("slack conversations.replies returned no messages")
673→+	}
674→+	return payload.Messages[0].Text, nil
675→+}
676→+
677→+type githubHTTPDispatcher struct {
678→+	token      string
679→+	baseURL    string
680→+	eventType  string
681→+	repository string
682→+	client     *http.Client
683→+}
684→+
685→+func newGitHubHTTPDispatcher(token, baseURL, eventType, repository string) *githubHTTPDispatcher {
686→+	if baseURL == "" {
687→+		baseURL = defaultGitHubAPIBaseURL
688→+	}
689→+	if eventType == "" {
690→+		eventType = defaultSlackEventType
691→+	}
692→+	return &githubHTTPDispatcher{
693→+		token:      token,
694→+		baseURL:    strings.TrimRight(baseURL, "/"),
695→+		eventType:  eventType,
696→+		repository: repository,
697→+		client:     &http.Client{Timeout: 10 * time.Second},
698→+	}
699→+}

