1270→+package slacktriage
1271→+
1272→+import (
1273→+	"errors"
1274→+	"fmt"
1275→+	"strings"
1276→+)
1277→+
1278→+// ParentMessageMetadata captures the parsed machine-readable Slack alert metadata.
1279→+type ParentMessageMetadata struct {
1280→+	Repo         string
1281→+	Branch       string
1282→+	RunID        string
1283→+	RunURL       string
1284→+	SHA          string
1285→+	FailedAgents []string
1286→+}
1287→+
1288→+// ParseParentMessageMetadata extracts the stable meta line from a Slack failure alert.
1289→+func ParseParentMessageMetadata(body string) (ParentMessageMetadata, error) {
1290→+	const metaPrefix = "meta:"
1291→+
1292→+	for _, line := range strings.Split(body, "\n") {
1293→+		trimmed := strings.TrimSpace(line)
1294→+		if !strings.HasPrefix(trimmed, metaPrefix) {
1295→+			continue
1296→+		}
1297→+
1298→+		fields := strings.Fields(strings.TrimSpace(strings.TrimPrefix(trimmed, metaPrefix)))
1299→+		values := make(map[string]string, len(fields))
1300→+		for _, field := range fields {
1301→+			key, value, ok := strings.Cut(field, "=")
1302→+			if !ok || key == "" || value == "" {
1303→+				return ParentMessageMetadata{}, fmt.Errorf("invalid meta field %q", field)
1304→+			}
1305→+			if _, exists := values[key]; exists {
1306→+				return ParentMessageMetadata{}, fmt.Errorf("duplicate meta field %q", key)
1307→+			}
1308→+			values[key] = value
1309→+		}
1310→+
1311→+		metadata := ParentMessageMetadata{
1312→+			Repo:   values["repo"],
1313→+			Branch: values["branch"],
1314→+			RunID:  values["run_id"],
1315→+			RunURL: values["run_url"],
1316→+			SHA:    values["sha"],
1317→+		}
1318→+		if agents, ok := values["agents"]; ok && agents != "" {
1319→+			metadata.FailedAgents = splitAndTrimCSV(agents)
1320→+		}
1321→+
1322→+		if err := metadata.validate(); err != nil {
1323→+			return ParentMessageMetadata{}, err
1324→+		}
1325→+		return metadata, nil
1326→+	}
1327→+
1328→+	return ParentMessageMetadata{}, errors.New("meta line not found")
1329→+}
1330→+
1331→+func (m ParentMessageMetadata) validate() error {
1332→+	switch {
1333→+	case m.Repo == "":
1334→+		return errors.New("repo is required")
1335→+	case m.Branch == "":
1336→+		return errors.New("branch is required")
1337→+	case m.RunID == "":
1338→+		return errors.New("run_id is required")
1339→+	case m.RunURL == "":
1340→+		return errors.New("run_url is required")
1341→+	case m.SHA == "":
1342→+		return errors.New("sha is required")
1343→+	case len(m.FailedAgents) == 0:
1344→+		return errors.New("failed_agents is required")
1345→+	default:
1346→+		return nil
1347→+	}
1348→+}
1349→+
1350→+func splitAndTrimCSV(value string) []string {
1351→+	parts := strings.Split(value, ",")
1352→+	out := make([]string, 0, len(parts))
1353→+	for _, part := range parts {
1354→+		trimmed := strings.TrimSpace(part)
1355→+		if trimmed != "" {
1356→+			out = append(out, trimmed)
1357→+		}
1358→+	}
1359→+	return out
1360→+}
