158→func (h *triageHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
159→	if r.Method != http.MethodPost {
160→		http.Error(w, http.StatusText(http.StatusMethodNotAllowed), http.StatusMethodNotAllowed)
161→		return
162→	}
163→	defer r.Body.Close()
164→
165→	body, err := io.ReadAll(io.LimitReader(r.Body, h.maxBodyLen))
166→	if err != nil {
167→		http.Error(w, "read request body", http.StatusBadRequest)
168→		return
169→	}
170→
171→	if err := h.verifyRequest(r, body); err != nil {
172→		http.Error(w, http.StatusText(http.StatusUnauthorized), http.StatusUnauthorized)
173→		return
174→	}
175→
176→	var envelope slackEnvelope
177→	if err := json.Unmarshal(body, &envelope); err != nil {
178→		http.Error(w, "decode slack payload", http.StatusBadRequest)
179→		return
180→	}
181→
182→	switch envelope.Type {
183→	case slackEventTypeURLVerify:
184→		writeJSON(w, http.StatusOK, map[string]string{"challenge": envelope.Challenge})
185→	case slackEventTypeCallback:
186→		if err := h.handleEvent(r.Context(), envelope.Event); err != nil {
187→			http.Error(w, "process slack event", http.StatusInternalServerError)
188→			return
