21→	const metaPrefix = "meta:"
22→
23→	for _, line := range strings.Split(body, "\n") {
24→		trimmed := strings.TrimSpace(line)
25→		if !strings.HasPrefix(trimmed, metaPrefix) {
26→			continue
27→		}
28→
29→		fields := strings.Fields(strings.TrimSpace(strings.TrimPrefix(trimmed, metaPrefix)))
30→		values := make(map[string]string, len(fields))
31→		for _, field := range fields {
32→			key, value, ok := strings.Cut(field, "=")
33→			if !ok || key == "" || value == "" {
34→				return ParentMessageMetadata{}, fmt.Errorf("invalid meta field %q", field)
35→			}
36→			if _, exists := values[key]; exists {
37→				return ParentMessageMetadata{}, fmt.Errorf("duplicate meta field %q", key)
38→			}
39→			values[key] = value
40→		}
41→
42→		metadata := ParentMessageMetadata{
43→			Repo:   values["repo"],
44→			Branch: values["branch"],
45→			RunID:  values["run_id"],
46→			RunURL: values["run_url"],
47→			SHA:    values["sha"],
48→		}
49→		if agents, ok := values["agents"]; ok && agents != "" {
50→			metadata.FailedAgents = splitAndTrimCSV(agents)
51→		}
52→
53→		if err := metadata.validate(); err != nil {
54→			return ParentMessageMetadata{}, err
55→		}
56→		return metadata, nil
57→	}
58→
59→	return ParentMessageMetadata{}, errors.New("meta line not found")
60→}
61→
62→func (m ParentMessageMetadata) validate() error {
63→	switch {
64→	case m.Repo == "":
65→		return errors.New("repo is required")
66→	case m.Branch == "":
67→		return errors.New("branch is required")
68→	case m.RunID == "":
69→		return errors.New("run_id is required")
70→	case m.RunURL == "":
71→		return errors.New("run_url is required")
72→	case m.SHA == "":
73→		return errors.New("sha is required")
74→	case len(m.FailedAgents) == 0:
75→		return errors.New("failed_agents is required")
76→	default:
77→		return nil
78→	}
79→}
80→
81→func splitAndTrimCSV(value string) []string {
82→	parts := strings.Split(value, ",")
83→	out := make([]string, 0, len(parts))
84→	for _, part := range parts {
85→		trimmed := strings.TrimSpace(part)
86→		if trimmed != "" {
87→			out = append(out, trimmed)
88→		}
89→	}
90→	return out
91→}
