226→func (h *triageHandler) handleEvent(ctx context.Context, event slackEvent) error {
227→	if event.Type != slackInnerEventTypeMessage {
228→		return nil
229→	}
230→	if event.Subtype != "" || event.BotID != "" {
231→		return nil
232→	}
233→	if event.ThreadTS == "" || event.ThreadTS == event.Ts {
234→		return nil
235→	}
236→	if !slacktriage.IsTriageTrigger(event.Text) {
237→		return nil
238→	}
239→	if h.slack == nil {
240→		return errors.New("slack fetcher is not configured")
241→	}
242→	if h.github == nil {
243→		return errors.New("github dispatcher is not configured")
244→	}
245→	if event.Channel == "" {
246→		return errors.New("channel is required")
247→	}
248→
249→	parentBody, err := h.slack.FetchParentMessage(ctx, event.Channel, event.ThreadTS)
250→	if err != nil {
251→		return fmt.Errorf("fetch parent message: %w", err)
252→	}
253→
254→	metadata, err := slacktriage.ParseParentMessageMetadata(parentBody)
255→	if err != nil {
256→		return fmt.Errorf("parse parent message metadata: %w", err)
257→	}
258→	if h.cfg.AllowedRepo != "" && metadata.Repo != h.cfg.AllowedRepo {
259→		return nil
260→	}
261→
262→	payload := slacktriage.NewDispatchPayload(metadata, event.Channel, event.ThreadTS, event.User)
263→	if err := h.github.DispatchRepositoryEvent(ctx, payload); err != nil {
264→		return fmt.Errorf("dispatch repository event: %w", err)
265→	}
266→	return nil
267→}
