394→func (d *githubHTTPDispatcher) DispatchRepositoryEvent(ctx context.Context, payload slacktriage.DispatchPayload) error {
395→	body, err := json.Marshal(struct {
396→		EventType     string                      `json:"event_type"`
397→		ClientPayload slacktriage.DispatchPayload `json:"client_payload"`
398→	}{
399→		EventType:     d.eventType,
400→		ClientPayload: payload,
401→	})
402→	if err != nil {
403→		return fmt.Errorf("marshal github dispatch payload: %w", err)
404→	}
405→
406→	endpoint := fmt.Sprintf("%s/repos/%s/dispatches", d.baseURL, d.repository)
407→	req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(body))
408→	if err != nil {
409→		return fmt.Errorf("build github dispatch request: %w", err)
410→	}
411→	req.Header.Set("Authorization", "Bearer "+d.token)
412→	req.Header.Set("Accept", "application/vnd.github+json")
413→	req.Header.Set("Content-Type", "application/json")
414→
415→	//nolint:gosec // GitHub API base URL and repository are operator-configured.
416→	resp, err := d.client.Do(req)
417→	if err != nil {
418→		return fmt.Errorf("call github dispatch endpoint: %w", err)
419→	}
420→	defer resp.Body.Close()
421→
422→	if resp.StatusCode != http.StatusNoContent {
423→		responseBody, readErr := io.ReadAll(io.LimitReader(resp.Body, 4096))
424→		if readErr != nil {
425→			return fmt.Errorf("github dispatch failed: %s (read response): %w", resp.Status, readErr)
426→		}
427→		if len(responseBody) > 0 {
428→			return fmt.Errorf("github dispatch failed: %s: %s", resp.Status, strings.TrimSpace(string(responseBody)))
429→		}
430→		return fmt.Errorf("github dispatch failed: %s", resp.Status)
431→	}
432→
433→	return nil
434→}
