 84→		RequestTolerance: defaultRequestTolerance,
 85→	}
 86→
 87→	if tolerance := os.Getenv("SLACK_REQUEST_TOLERANCE"); tolerance != "" {
 88→		d, err := time.ParseDuration(tolerance)
 89→		if err != nil {
 90→			return Config{}, fmt.Errorf("parse SLACK_REQUEST_TOLERANCE: %w", err)
 91→		}
 92→		cfg.RequestTolerance = d
 93→	}
