158→func (h *triageHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
159→	if r.Method != http.MethodPost {
160→		http.Error(w, http.StatusText(http.StatusMethodNotAllowed), http.StatusMethodNotAllowed)
161→		return
162→	}
163→	defer r.Body.Close()
164→
165→	body, err := io.ReadAll(io.LimitReader(r.Body, h.maxBodyLen))
166→	if err != nil {
167→		http.Error(w, "read request body", http.StatusBadRequest)
168→		return
169→	}
170→
171→	if err := h.verifyRequest(r, body); err != nil {
172→		http.Error(w, http.StatusText(http.StatusUnauthorized), http.StatusUnauthorized)
173→		return
174→	}
175→
176→	var envelope slackEnvelope
177→	if err := json.Unmarshal(body, &envelope); err != nil {
178→		http.Error(w, "decode slack payload", http.StatusBadRequest)
179→		return
180→	}
181→
182→	switch envelope.Type {
183→	case slackEventTypeURLVerify:
184→		writeJSON(w, http.StatusOK, map[string]string{"challenge": envelope.Challenge})
185→	case slackEventTypeCallback:
186→		if err := h.handleEvent(r.Context(), envelope.Event); err != nil {
187→			http.Error(w, "process slack event", http.StatusInternalServerError)
188→			return
189→		}
190→		w.WriteHeader(http.StatusOK)
191→	default:
192→		w.WriteHeader(http.StatusOK)
193→	}
194→}
195→
196→func (h *triageHandler) verifyRequest(r *http.Request, body []byte) error {
197→	timestamp := r.Header.Get(slackTimestampHeader)
198→	signature := r.Header.Get(slackSignatureHeader)
199→	if timestamp == "" || signature == "" {
200→		return errors.New("missing slack signature headers")
201→	}
202→
203→	parsed, err := strconv.ParseInt(timestamp, 10, 64)
204→	if err != nil {
205→		return fmt.Errorf("invalid slack timestamp: %w", err)
206→	}
207→
208→	requestTime := time.Unix(parsed, 0)
209→	now := h.now()
210→	if absDuration(now.Sub(requestTime)) > h.cfg.RequestTolerance {
211→		return errors.New("stale slack request")
212→	}
213→
214→	mac := hmac.New(sha256.New, []byte(h.cfg.SigningSecret))
215→	if _, err := mac.Write([]byte("v0:" + timestamp + ":" + string(body))); err != nil {
216→		return fmt.Errorf("sign slack request: %w", err)
217→	}
218→	expected := "v0=" + hex.EncodeToString(mac.Sum(nil))
219→	if !hmac.Equal([]byte(expected), []byte(signature)) {
220→		return errors.New("invalid slack signature")
221→	}
222→
223→	return nil
224→}
