318→func (c *slackHTTPClient) FetchParentMessage(ctx context.Context, channel, threadTS string) (string, error) {
319→	endpoint, err := url.Parse(c.baseURL + "/conversations.replies")
320→	if err != nil {
321→		return "", fmt.Errorf("parse slack conversations.replies url: %w", err)
322→	}
323→
324→	query := endpoint.Query()
325→	query.Set("channel", channel)
326→	query.Set("ts", threadTS)
327→	query.Set("inclusive", "true")
328→	query.Set("limit", "1")
329→	endpoint.RawQuery = query.Encode()
330→
331→	req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint.String(), nil)
332→	if err != nil {
333→		return "", fmt.Errorf("build slack conversations.replies request: %w", err)
334→	}
335→	req.Header.Set("Authorization", "Bearer "+c.token)
336→
337→	//nolint:gosec // Slack API base URL is operator-configured.
338→	resp, err := c.client.Do(req)
339→	if err != nil {
340→		return "", fmt.Errorf("call slack conversations.replies: %w", err)
341→	}
342→	defer resp.Body.Close()
343→
344→	if resp.StatusCode != http.StatusOK {
345→		return "", fmt.Errorf("slack conversations.replies returned %s", resp.Status)
346→	}
347→
348→	var payload struct {
349→		OK       bool   `json:"ok"`
350→		Error    string `json:"error,omitempty"`
351→		Messages []struct {
352→			Text string `json:"text"`
353→		} `json:"messages"`
354→	}
355→	if err := json.NewDecoder(resp.Body).Decode(&payload); err != nil {
356→		return "", fmt.Errorf("decode slack conversations.replies response: %w", err)
357→	}
358→	if !payload.OK {
359→		if payload.Error == "" {
360→			payload.Error = "unknown error"
361→		}
362→		return "", fmt.Errorf("slack conversations.replies error: %s", payload.Error)
363→	}
364→	if len(payload.Messages) == 0 {
365→		return "", errors.New("slack conversations.replies returned no messages")
366→	}
367→	return payload.Messages[0].Text, nil
368→}
